const fs=require('fs');
const puppeteer=require('puppeteer-core');
const PRODUCT='bfdaeefcce715ff36bf8f9838b6401ffcc477b9c';
const base='http://127.0.0.1:8000/';
const routes=['index.html','corporate.html','energy.html','products.html','product.html','urea-46.html','caustic-soda-solid.html','sodium-sulphate-anhydrous.html','sales.html','technology.html','evidence-axis.html','ventures.html','contact.html','privacy.html','legal.html','404.html'];
const vps=[{name:'1920x1080',width:1920,height:1080},{name:'1440x900',width:1440,height:900},{name:'768x1024',width:768,height:1024},{name:'390x844',width:390,height:844},{name:'360x800',width:360,height:800}];
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const out={productSha:PRODUCT,cases:{},failures:[],summary:{cases:0,horizontalOverflow:0,brokenImages:0,consoleErrors:0,pageErrors:0,requestFailures:0,missingShell:0,missingSamePageFragments:0}};
(async()=>{
 const browser=await puppeteer.launch({headless:true,executablePath:process.env.CHROME,args:['--no-sandbox','--disable-dev-shm-usage','--autoplay-policy=user-gesture-required']});
 fs.mkdirSync('gate-a-followup/full',{recursive:true});
 for(const route of routes){out.cases[route]={};for(const vp of vps){const p=await browser.newPage();await p.setViewport({width:vp.width,height:vp.height,deviceScaleFactor:1});const consoleErrors=[],pageErrors=[],requestFailures=[];p.on('console',m=>{if(m.type()==='error')consoleErrors.push(m.text())});p.on('pageerror',e=>pageErrors.push(String(e)));p.on('requestfailed',r=>requestFailures.push({url:r.url(),error:r.failure()?.errorText||''}));let status=null;try{const res=await p.goto(base+route,{waitUntil:'load',timeout:30000});status=res?.status()??null;await p.evaluate(()=>document.fonts?.ready||Promise.resolve());await p.evaluate(async()=>{const h=Math.max(document.body.scrollHeight,document.documentElement.scrollHeight);for(let y=0;y<h;y+=Math.max(300,innerHeight*.7)){scrollTo(0,y);await new Promise(r=>setTimeout(r,35))}scrollTo(0,0);await new Promise(r=>setTimeout(r,120));const imgs=[...document.images];await Promise.all(imgs.map(img=>img.complete?Promise.resolve():new Promise(resolve=>{let done=false;const end=()=>{if(done)return;done=true;resolve()};img.addEventListener('load',end,{once:true});img.addEventListener('error',end,{once:true});setTimeout(end,2500)})));});await sleep(60);}catch(e){pageErrors.push(String(e))}
 const data=await p.evaluate(()=>{const vis=e=>{if(!e)return false;const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>0&&r.height>0};const imgs=[...document.images].map(i=>({src:i.getAttribute('src')||'',complete:i.complete,naturalWidth:i.naturalWidth,naturalHeight:i.naturalHeight}));const samePageFragments=[];for(const a of document.querySelectorAll('a[href^="#"]')){const href=a.getAttribute('href');if(href&&href.length>1)samePageFragments.push({href,exists:Boolean(document.getElementById(decodeURIComponent(href.slice(1))))})}return{viewport:{w:innerWidth,h:innerHeight},scrollWidth:document.documentElement.scrollWidth,scrollHeight:document.documentElement.scrollHeight,horizontalOverflow:document.documentElement.scrollWidth>innerWidth+1,images:imgs,brokenImages:imgs.filter(i=>!i.complete||i.naturalWidth<1||i.naturalHeight<1),header:Boolean(document.querySelector('.site-header[data-header]')),footer:Boolean(document.querySelector('footer.site-footer')),main:Boolean(document.querySelector('main')),primaryNavLinks:document.querySelectorAll('#primary-nav a[href]').length,visibleActions:[...document.querySelectorAll('main a[href],main button')].filter(vis).length,samePageFragments};});
 const row={status,...data,consoleErrors,pageErrors,requestFailures};out.cases[route][vp.name]=row;out.summary.cases++;if(row.horizontalOverflow)out.summary.horizontalOverflow++;out.summary.brokenImages+=row.brokenImages.length;out.summary.consoleErrors+=consoleErrors.length;out.summary.pageErrors+=pageErrors.length;out.summary.requestFailures+=requestFailures.length;if(!row.header||!row.footer||!row.main||row.primaryNavLinks!==6)out.summary.missingShell++;out.summary.missingSamePageFragments+=row.samePageFragments.filter(x=>!x.exists).length;
 if(![200,304].includes(status))out.failures.push({route,vp:vp.name,type:'status',detail:status});if(row.horizontalOverflow)out.failures.push({route,vp:vp.name,type:'horizontal-overflow',detail:{scrollWidth:row.scrollWidth,viewport:vp.width}});if(row.brokenImages.length)out.failures.push({route,vp:vp.name,type:'broken-images',detail:row.brokenImages});if(consoleErrors.length)out.failures.push({route,vp:vp.name,type:'console-errors',detail:consoleErrors});if(pageErrors.length)out.failures.push({route,vp:vp.name,type:'page-errors',detail:pageErrors});if(requestFailures.length)out.failures.push({route,vp:vp.name,type:'request-failures',detail:requestFailures});if(!row.header||!row.footer||!row.main||row.primaryNavLinks!==6)out.failures.push({route,vp:vp.name,type:'shell',detail:{header:row.header,footer:row.footer,main:row.main,links:row.primaryNavLinks}});const missing=row.samePageFragments.filter(x=>!x.exists);if(missing.length)out.failures.push({route,vp:vp.name,type:'same-page-fragments',detail:missing});
 if(['index.html','products.html','corporate.html','energy.html'].includes(route))await p.screenshot({path:`gate-a-followup/full/${route.replace('.html','')}-${vp.name}.png`,fullPage:false});await p.close();}}
 fs.writeFileSync('gate-a-followup/full/full-report.json',JSON.stringify(out,null,2));console.log(JSON.stringify({productSha:PRODUCT,summary:out.summary,failures:out.failures},null,2));await browser.close();if(out.summary.cases!==80||out.failures.length)process.exit(2);
})().catch(e=>{console.error(e);process.exit(1)});
